      }
      var ev = it.best_evidence;
      if (ev) {
        d += '<h4 style="margin-top:14px">最强证据</h4><div class="evidence">';
        if (ev.content) d += '<div class="ev-content">' + renderMarkdown(ev.content) + "</div>";
