"""Layout sanity checks at desktop and mobile widths."""

import sys

from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:18808"

CHECKS = """
() => {
  const out = [];
  const vw = document.documentElement.clientWidth;
  const vis = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return {w: Math.round(r.width), h: Math.round(r.height), top: Math.round(r.top + window.scrollY)};
  };
  // any element wider than viewport (excluding intentional scroll containers)?
  const wide = [];
  document.querySelectorAll('body *').forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.width > vw + 1 && !el.closest('.table-scroll, .cmd-block, .sessions-table-wrap')) {
      wide.push(el.tagName + '.' + (el.className || '') + ':' + Math.round(r.width));
    }
  });
  out.push(['overflowing_elements', wide]);
  out.push(['hero_h1', vis('header.hero h1')]);
  out.push(['radar_canvas', vis('#radar-chart canvas')]);
  out.push(['hero_buttons', vis('header.hero .btns')]);
  out.push(['footer', vis('footer')]);
  const c = document.querySelector('#radar-chart canvas');
  out.push(['canvas_pixels', c ? [c.width, c.height] : null]);
  return out;
}
"""

def main() -> int:
    failed = []
    with sync_playwright() as p:
        browser = p.chromium.launch(channel="chrome", headless=True)
        for label, w, h in [("desktop", 1440, 900), ("mobile", 375, 812)]:
            page = browser.new_page(viewport={"width": w, "height": h})
            page.goto(BASE + "/", wait_until="networkidle")
            page.wait_for_timeout(1500)
            results = dict(page.evaluate(CHECKS))
            print(f"--- {label} ({w}px) ---")
            for k, v in results.items():
                print(f"  {k}: {v}")
            if results["overflowing_elements"]:
                failed.append(f"{label}: overflowing elements {results['overflowing_elements']}")
            if not results["radar_canvas"] or results["radar_canvas"]["w"] < 200:
                failed.append(f"{label}: radar canvas too small: {results['radar_canvas']}")
            if results["canvas_pixels"] and results["canvas_pixels"][0] < 200:
                failed.append(f"{label}: echarts canvas backing store too small")
            if not results["hero_buttons"] or results["hero_buttons"]["w"] < 100:
                failed.append(f"{label}: hero buttons missing")
            page.close()
        browser.close()
    print("\n".join("FAILED: " + f for f in failed) if failed else "ALL LAYOUT CHECKS PASSED")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

